import Handlebars from 'handlebars';
import _math from '../helper/funcs/_math.js';

// Реєструємо хелпер у Handlebars
Handlebars.registerHelper('_math', _math);

describe('_math helper', () => {

  // Тест для додавання
  it('should add two numbers', () => {
    const template = Handlebars.compile('{{_math operator="+" arg1=10 arg2=5}}');
    const result = template({});
    expect(result).toBe('15');
  });

  // Тест для віднімання
  it('should subtract two numbers', () => {
    const template = Handlebars.compile('{{_math operator="-" arg1=10 arg2=5}}');
    const result = template({});
    expect(result).toBe('5');
  });

  // Тест для множення
  it('should multiply two numbers', () => {
    const template = Handlebars.compile('{{_math operator="*" arg1=10 arg2=5}}');
    const result = template({});
    expect(result).toBe('50');
  });

  // Тест для ділення
  it('should divide two numbers', () => {
    const template = Handlebars.compile('{{_math operator="/" arg1=10 arg2=5}}');
    const result = template({});
    expect(result).toBe('2');
  });

  // Тест для залишку від ділення (modulus)
  it('should return the remainder of division', () => {
    const template = Handlebars.compile('{{_math operator="%" arg1=10 arg2=3}}');
    const result = template({});
    expect(result).toBe('1');
  });

  // Тест для обчислення відсотків
  it('should calculate percentage', () => {
    const template = Handlebars.compile('{{_math operator=".%" arg1=50 arg2=200}}');
    const result = template({});
    expect(result).toBe('25%');
  });

  // Тест для використання аргументів без опцій
  it('should add two numbers passed directly', () => {
    const template = Handlebars.compile('{{_math "10" "+" "5"}}');
    const result = template({});
    expect(result).toBe('15');
  });

  // Тест для неіснуючого оператора
  it('should return "operator is not defined" for unknown operator', () => {
    const template = Handlebars.compile('{{_math operator="unknown" arg1=10 arg2=5}}');
    const result = template({});
    expect(result).toBe('operator is not defined');
  });

  // Тест для відсутніх аргументів
  it('should return an empty string if any argument is missing', () => {
    const template = Handlebars.compile('{{_math operator="+" arg1=10}}');
    const result = template({});
    expect(result).toBe('');
  });
});
